#include <iostream>
#include <string>
#include <vector>
using namespace std;

const int MOD = 1000000007;

int posl(const string& s) {
    vector<int> l(s.size());
    l[0] = -1;

    for (int k = 1; k < static_cast<int>(s.size()); ++k) {
        int j = l[k - 1];
        while (j >= 0 && s[j + 1] != s[k]) {
            j = l[j];
        }
        if (j == -1 && s[k] != s[0]) {
            --j;
        }
        l[k] = j + 1;
    }

    return l.back() + 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string a, b;
    cin >> a >> b;

    string combined = b + b + '$' + a + a;

    int k = posl(a);
    int period = -1;
    if (2 * k >= static_cast<int>(a.size())) {
        period = static_cast<int>(a.size()) - k;
    }

    int pp = posl(combined);
    pp = 2 * static_cast<int>(a.size()) - pp;

    if (pp >= static_cast<int>(a.size())) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> positions;
    int position = pp;
    positions.push_back(position);

    if (period != -1) {
        position += period;
        while (position < static_cast<int>(a.size())) {
            positions.push_back(position);
            position += period;
        }
    }

    cin >> k;

    const int n = static_cast<int>(a.size());
    vector<int> previous(n, 0);
    vector<int> current(n, 0);
    previous[0] = 1;

    int sum = 1;

    for (int i = 1; i <= k; ++i) {
        long long newSum = 0;

        for (int j = 0; j < n; ++j) {
            current[j] = sum - previous[j];
            if (current[j] < 0) {
                current[j] += MOD;
            }
            newSum += current[j];
        }

        sum = static_cast<int>(newSum % MOD);
        previous.swap(current);
    }

    int answer = 0;
    for (int index : positions) {
        answer += previous[index];
        if (answer >= MOD) {
            answer -= MOD;
        }
    }

    cout << answer << '\n';
    return 0;
}

